// CALLEE: beacon_chain/spec/engine_authentication.nim:getSignedIatToken (lines 61-83)
func getSignedIatToken*(key: openArray[byte], time: int64): string =
  getSignedToken(key, $getIatToken(time))

func parseJwtTokenValue*(input: string): Result[seq[byte], cstring] =
  let secret = utils.fromHex(input)
  if secret.len == JWT_SECRET_LEN:  # 256-bit requirement enforced
    ok(secret)
  else:
    err("The JWT secret should be 256 bits and hex-encoded")

// PRIMARY: beacon_chain/spec/engine_authentication.nim:parseJwtTokenValue (lines 64-83)
// JWT secret validation - enforces 256-bit minimum
func parseJwtTokenValue*(input: string): Result[seq[byte], cstring] =
  # Secret JWT key is parsed in constant time using nimcrypto
  let secret = utils.fromHex(input)
  if secret.len == JWT_SECRET_LEN:  # 32 bytes = 256 bits
    ok(secret)
  else:
    err("The JWT secret should be 256 bits and hex-encoded")

proc loadJwtSecretFile*(jwtSecretFile: InputFile): Result[seq[byte], cstring] =
  try:
    let lines = readLines(string jwtSecretFile, 1)
    if lines.len > 0:
      parseJwtTokenValue(lines[0])
    else:
      err("The JWT token file should not be empty")
  except IOError:
    err("couldn't open specified JWT secret file")

// PRIMARY: beacon_chain/spec/helpers.nim:compute_execution_block_hash (lines 528-544)
// CL computes and includes parent_beacon_block_root in execution block header
func compute_execution_block_hash*(body: ForkyBeaconBlockBody, parentRoot: Eth2Digest): Eth2Digest =
  when typeof(body).kind >= ConsensusFork.Electra:
    body.execution_payload.toExecutionBlockHeader(
        Opt.some parentRoot, Opt.some body.execution_requests.computeRequestsHash())
      .computeRlpHash().to(Eth2Digest)
  elif typeof(body).kind >= ConsensusFork.Deneb:
    body.execution_payload.toExecutionBlockHeader(
        Opt.some parentRoot)
      .computeRlpHash().to(Eth2Digest)
  else:
    body.execution_payload.toExecutionBlockHeader(Opt.none(Eth2Digest))
      .computeRlpHash().to(Eth2Digest)

// PRIMARY: beacon_chain/spec/state_transition_block.nim:process_deposit (lines 349-391)
// nimbus-eth2 uses SSZ-typed DepositData struct rather than raw ABI offsets;
// field ordering is enforced by the type system (pubkey, withdrawal_credentials, amount, signature)
proc process_deposit*(
    cfg: RuntimeConfig, state: var ForkyBeaconState,
    bucketSortedValidators: var BucketSortedValidators,
    deposit: Deposit, flags: UpdateFlags): Result[void, cstring] =
  if not is_valid_merkle_branch(
    hash_tree_root(deposit.data),
    deposit.proof,
    DEPOSIT_CONTRACT_TREE_DEPTH + 1,
    state.eth1_deposit_index,
    state.eth1_data.deposit_root):
    return err("process_deposit: deposit Merkle validation failed")
  state.eth1_deposit_index += 1
  apply_deposit(cfg, state, bucketSortedValidators, deposit.data, flags)

// PRIMARY: beacon_chain/spec/state_transition_block.nim:process_deposit_request (lines 372-391)
// Electra: deposit fields validated via SSZ type constraints (BLSPubKey=48B, Bytes32=32B, uint64=8B, BLSSignature=96B, uint64=8B)
func process_deposit_request*(
    cfg: RuntimeConfig,
    state: var (electra.BeaconState | fulu.BeaconState | gloas.BeaconState),
    deposit_request: DepositRequest,
    flags: UpdateFlags): Result[void, cstring] =
  if state.deposit_requests_start_index ==
      UNSET_DEPOSIT_REQUESTS_START_INDEX:
    state.deposit_requests_start_index = deposit_request.index
  if state.pending_deposits.add(PendingDeposit(
      pubkey: deposit_request.pubkey,
      withdrawal_credentials: deposit_request.withdrawal_credentials,
      amount: deposit_request.amount,
      signature: deposit_request.signature,
      slot: state.slot)):
    ok()
  else:
    err("process_deposit_request: couldn't add deposit to pending_deposits")

// PRIMARY: beacon_chain/spec/helpers.nim:computeRequestsHash (lines 451-472)
// Uses computeDigest (SHA-256 via nimcrypto) - two-level hashing per EIP-7685
func computeRequestsHash(requests: electra.ExecutionRequests): EthHash32 =
  template individualHash(requestType, requestList): Digest =
    computeDigest:
      h.update([requestType.byte])
      for request in requestList:
        h.update SSZ.encode(request)

  let requestsHash = computeDigest:
    template mixInRequests(requestType, requestList): untyped =
      if requestList.len > 0:
        h.update(individualHash(requestType, requestList).data)
    static:
      doAssert DEPOSIT_REQUEST_TYPE < WITHDRAWAL_REQUEST_TYPE
      doAssert WITHDRAWAL_REQUEST_TYPE < CONSOLIDATION_REQUEST_TYPE
    mixInRequests(DEPOSIT_REQUEST_TYPE, requests.deposits)
    mixInRequests(WITHDRAWAL_REQUEST_TYPE, requests.withdrawals)
    mixInRequests(CONSOLIDATION_REQUEST_TYPE, requests.consolidations)
  requestsHash.to(EthHash32)
